import { useId, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Input, Stack, Tag } from '@jinx-ui/react';

type TagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  maxTags?: number;
  onChange: (tags: string[]) => void;
};

export default function TagPicker({
  label = 'Теги',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  maxTags,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const listId = useId();

  const isFull = maxTags !== undefined && tags.length >= maxTags;

  const apply = (next: string[]) => {
    setTags(next);
    onChange(next);
  };

  const commit = () => {
    const tag = draft.trim().replace(/\s+/g, ' ');
    setDraft('');
    if (!tag || isFull) return;
    if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) return;
    apply([...tags, tag]);
  };

  const remove = (index: number) => {
    apply(tags.filter((_, i) => i !== index));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      commit();
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      remove(tags.length - 1);
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <Input
        label={label}
        value={draft}
        placeholder={isFull ? '' : placeholder}
        disabled={isFull}
        aria-describedby={listId}
        onChange={(event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={commit}
      />
      <Stack
        id={listId}
        role="list"
        direction="row"
        wrap
        gap="var(--jx-space-1)"
        aria-label={label}
      >
        {tags.map((tag, index) => (
          <Tag
            key={tag}
            role="listitem"
            onRemove={() => remove(index)}
            aria-label={`Удалить тег ${tag}`}
          >
            {tag}
          </Tag>
        ))}
      </Stack>
    </Stack>
  );
}

